class FfiChangeVerb(enum.Enum):
    """
    Engine verb that produced a subscription change event.
"""

    REPLACE = 0

    APPEND = 1

    DELETE = 2

    FORMAT = 3

    UNKNOWN = 4
    """
    The Engine returned a change verb this FFI binding does not yet recognize.
    Treat as an unknown change and upgrade the binding.
"""



class _UniffiFfiConverterTypeFfiChangeVerb(_UniffiConverterRustBuffer):
    @staticmethod
    def read(buf):
        variant = buf.read_i32()
        if variant == 1:
            return FfiChangeVerb.REPLACE
        if variant == 2:
            return FfiChangeVerb.APPEND
        if variant == 3:
            return FfiChangeVerb.DELETE
        if variant == 4:
            return FfiChangeVerb.FORMAT
        if variant == 5:
            return FfiChangeVerb.UNKNOWN
        raise InternalError("Raw enum value doesn't match any cases")

    @staticmethod
    def check_lower(value):
        if value == FfiChangeVerb.REPLACE:
            return
        if value == FfiChangeVerb.APPEND:
            return
        if value == FfiChangeVerb.DELETE:
            return
        if value == FfiChangeVerb.FORMAT:
            return
        if value == FfiChangeVerb.UNKNOWN:
            return
        raise ValueError(value)

    @staticmethod
    def write(value, buf):
        if value == FfiChangeVerb.REPLACE:
            buf.write_i32(1)
        if value == FfiChangeVerb.APPEND:
            buf.write_i32(2)
        if value == FfiChangeVerb.DELETE:
            buf.write_i32(3)
        if value == FfiChangeVerb.FORMAT:
            buf.write_i32(4)
        if value == FfiChangeVerb.UNKNOWN:
            buf.write_i32(5)



