class FfiEtagMatcher:
    """
    ETag matcher used by FFI write preconditions.
"""
    def __init__(self):
        raise RuntimeError("FfiEtagMatcher cannot be instantiated directly")

    # Each enum variant is a nested class of the enum itself.
    @dataclass
    class ANY:

        def __init__(self, ):
            pass





        def __str__(self):
            return "FfiEtagMatcher.ANY()".format()
        def __eq__(self, other):
            if not isinstance(other, FfiEtagMatcher):
                return NotImplemented
            if not other.is_ANY():
                return False
            return True

    @dataclass
    class STRONG:

        def __init__(self, etag:str):
            self.etag = etag


            pass





        def __str__(self):
            return "FfiEtagMatcher.STRONG(etag={})".format(self.etag)
        def __eq__(self, other):
            if not isinstance(other, FfiEtagMatcher):
                return NotImplemented
            if not other.is_STRONG():
                return False
            if self.etag != other.etag:
                return False
            return True

    @dataclass
    class WEAK:

        def __init__(self, etag:str):
            self.etag = etag


            pass





        def __str__(self):
            return "FfiEtagMatcher.WEAK(etag={})".format(self.etag)
        def __eq__(self, other):
            if not isinstance(other, FfiEtagMatcher):
                return NotImplemented
            if not other.is_WEAK():
                return False
            if self.etag != other.etag:
                return False
            return True



    # For each variant, we have `is_NAME` and `is_name` methods for easily checking
    # whether an instance is that variant.
    def is_ANY(self) -> bool:
        return isinstance(self, FfiEtagMatcher.ANY)
    def is_any(self) -> bool:
        return isinstance(self, FfiEtagMatcher.ANY)
    def is_STRONG(self) -> bool:
        return isinstance(self, FfiEtagMatcher.STRONG)
    def is_strong(self) -> bool:
        return isinstance(self, FfiEtagMatcher.STRONG)
    def is_WEAK(self) -> bool:
        return isinstance(self, FfiEtagMatcher.WEAK)
    def is_weak(self) -> bool:
        return isinstance(self, FfiEtagMatcher.WEAK)


# Now, a little trick - we make each nested variant class be a subclass of the main
# enum class, so that method calls and instance checks etc will work intuitively.
# We might be able to do this a little more neatly with a metaclass, but this'll do.
FfiEtagMatcher.ANY = type("FfiEtagMatcher.ANY", (FfiEtagMatcher.ANY, FfiEtagMatcher,), {})  # type: ignore
FfiEtagMatcher.STRONG = type("FfiEtagMatcher.STRONG", (FfiEtagMatcher.STRONG, FfiEtagMatcher,), {})  # type: ignore
FfiEtagMatcher.WEAK = type("FfiEtagMatcher.WEAK", (FfiEtagMatcher.WEAK, FfiEtagMatcher,), {})  # type: ignore




class _UniffiFfiConverterTypeFfiEtagMatcher(_UniffiConverterRustBuffer):
    @staticmethod
    def read(buf):
        variant = buf.read_i32()
        if variant == 1:
            return FfiEtagMatcher.ANY(
            )
        if variant == 2:
            return FfiEtagMatcher.STRONG(
                _UniffiFfiConverterString.read(buf),
            )
        if variant == 3:
            return FfiEtagMatcher.WEAK(
                _UniffiFfiConverterString.read(buf),
            )
        raise InternalError("Raw enum value doesn't match any cases")

    @staticmethod
    def check_lower(value):
        if value.is_ANY():
            return
        if value.is_STRONG():
            _UniffiFfiConverterString.check_lower(value.etag)
            return
        if value.is_WEAK():
            _UniffiFfiConverterString.check_lower(value.etag)
            return
        raise ValueError(value)

    @staticmethod
    def write(value, buf):
        if value.is_ANY():
            buf.write_i32(1)
        if value.is_STRONG():
            buf.write_i32(2)
            _UniffiFfiConverterString.write(value.etag, buf)
        if value.is_WEAK():
            buf.write_i32(3)
            _UniffiFfiConverterString.write(value.etag, buf)



class _UniffiFfiConverterSequenceTypeFfiEtagMatcher(_UniffiConverterRustBuffer):
    @classmethod
    def check_lower(cls, value):
        for item in value:
            _UniffiFfiConverterTypeFfiEtagMatcher.check_lower(item)

    @classmethod
    def write(cls, value, buf):
        items = len(value)
        buf.write_i32(items)
        for item in value:
            _UniffiFfiConverterTypeFfiEtagMatcher.write(item, buf)

    @classmethod
    def read(cls, buf):
        count = buf.read_i32()
        if count < 0:
            raise InternalError("Unexpected negative sequence length")

        return [
            _UniffiFfiConverterTypeFfiEtagMatcher.read(buf) for i in range(count)
        ]

