class FfiSubscriptionNextKind(enum.Enum):
    """
    Result kind returned by `FfiSubscription.next`.
"""

    EVENT = 0

    TIMEOUT = 1

    LAGGED = 2

    RESET = 3

    CLOSED = 4

    UNKNOWN = 5
    """
    The Engine returned a subscription state this FFI binding does not yet
    recognize. Treat as indeterminate and upgrade the binding.
"""



class _UniffiFfiConverterTypeFfiSubscriptionNextKind(_UniffiConverterRustBuffer):
    @staticmethod
    def read(buf):
        variant = buf.read_i32()
        if variant == 1:
            return FfiSubscriptionNextKind.EVENT
        if variant == 2:
            return FfiSubscriptionNextKind.TIMEOUT
        if variant == 3:
            return FfiSubscriptionNextKind.LAGGED
        if variant == 4:
            return FfiSubscriptionNextKind.RESET
        if variant == 5:
            return FfiSubscriptionNextKind.CLOSED
        if variant == 6:
            return FfiSubscriptionNextKind.UNKNOWN
        raise InternalError("Raw enum value doesn't match any cases")

    @staticmethod
    def check_lower(value):
        if value == FfiSubscriptionNextKind.EVENT:
            return
        if value == FfiSubscriptionNextKind.TIMEOUT:
            return
        if value == FfiSubscriptionNextKind.LAGGED:
            return
        if value == FfiSubscriptionNextKind.RESET:
            return
        if value == FfiSubscriptionNextKind.CLOSED:
            return
        if value == FfiSubscriptionNextKind.UNKNOWN:
            return
        raise ValueError(value)

    @staticmethod
    def write(value, buf):
        if value == FfiSubscriptionNextKind.EVENT:
            buf.write_i32(1)
        if value == FfiSubscriptionNextKind.TIMEOUT:
            buf.write_i32(2)
        if value == FfiSubscriptionNextKind.LAGGED:
            buf.write_i32(3)
        if value == FfiSubscriptionNextKind.RESET:
            buf.write_i32(4)
        if value == FfiSubscriptionNextKind.CLOSED:
            buf.write_i32(5)
        if value == FfiSubscriptionNextKind.UNKNOWN:
            buf.write_i32(6)



